import math
import pygeohash as pgh

# Geohash cell (width, height) in km at the equator, by precision
CELL_KM = {4: (39.1, 19.5), 5: (4.9, 4.9), 6: (1.2, 0.61)}

def precision_for(radius_km: float, lat: float) -> int:
    # Finest cell at least as large as the radius: then 3x3 cells cover the circle
    shrink = math.cos(math.radians(lat))       # cells get narrower away from the equator
    fits = [p for p, (w, h) in CELL_KM.items() if min(w * shrink, h) >= radius_km]
    return max(fits, default=4)

def block_3x3(cell: str) -> list[str]:
    rows = (pgh.get_adjacent(cell, "top"), cell, pgh.get_adjacent(cell, "bottom"))
    return [*rows, *(pgh.get_adjacent(c, side) for c in rows for side in ("left", "right"))]

def cell_members(cell: str) -> list[tuple[str, float, float]]:
    if (hit := cache.get(f"cell:{cell}")) is not None:
        return hit                             # shared by every user inside this cell
    rows = replica.query("SELECT business_id, lat, lng FROM geo_index "
                         "WHERE geohash LIKE %s", cell + "%")  # prefix = any coarser cell
    cache.set(f"cell:{cell}", rows, ttl=jittered(86_400))      # static data: long TTL
    return rows

def nearby(lat: float, lng: float, radius_km: float, want: int = 20) -> list[tuple[float, str]]:
    p = precision_for(radius_km, lat)
    while True:
        cells = block_3x3(pgh.encode(lat, lng, precision=p))
        found = sorted((d, biz) for c in cells for biz, blat, blng in cell_members(c)
                       if (d := haversine_km(lat, lng, blat, blng)) <= radius_km)
        if len(found) >= want or p == 4:       # cells are coarse; the distance filter is exact
            return found[:want]
        p, radius_km = p - 1, radius_km * 4    # sparse area: 32x larger cell, wider radius
